mapper.insert:
INSERT INTO ads_campaign_performance (
    performance_id, tenant_id, campaign_id, spend, impressions, clicks, ctr, orders, acos, roas,
    period_start, period_end, created_at
) VALUES (
    #{performanceId}, #{tenantId}, #{campaignId}, #{spend}, #{impressions}, #{clicks}, #{ctr}, #{orders}, #{acos}, #{roas},
    #{periodStart}, #{periodEnd}, #{createdAt}
)

mapper.select:
SELECT performance_id, tenant_id, campaign_id, spend, impressions, clicks, ctr, orders, acos, roas,
       period_start, period_end, created_at
FROM ads_campaign_performance
WHERE tenant_id = #{tenantId}
  AND campaign_id = #{campaignId}
ORDER BY created_at DESC

SELECT performance_id, tenant_id, campaign_id, spend, impressions, clicks, ctr, orders, acos, roas,
       period_start, period_end, created_at
FROM ads_campaign_performance
WHERE tenant_id = #{tenantId}

    AND campaign_id = #{campaignId}


    AND period_start >= #{periodStart}


    AND period_end <= #{periodEnd}

ORDER BY created_at DESC

SELECT 'SUMMARY' AS performance_id, #{tenantId} AS tenant_id, #{campaignId} AS campaign_id, COALESCE(SUM(spend), 0) AS spend, COALESCE(SUM(impressions), 0) AS impressions, COALESCE(SUM(clicks), 0) AS clicks, CASE WHEN SUM(impressions) > 0 THEN SUM(clicks)::DECIMAL / SUM(impressions) ELSE 0 END AS ctr, COALESCE(SUM(orders), 0) AS orders, CASE WHEN SUM(orders) > 0 AND SUM(spend) > 0 THEN SUM(spend) / SUM(orders) ELSE 0 END AS acos, CASE WHEN SUM(spend) > 0 THEN SUM(orders)::DECIMAL / SUM(spend) ELSE 0 END AS roas, MIN(period_start) AS period_start, MAX(period_end) AS period_end, NOW() AS created_at FROM ads_campaign_performance WHERE tenant_id = #{tenantId} AND campaign_id = #{campaignId}
AND period_start >= #{periodStart}
AND period_end <= #{periodEnd}

SELECT group_id, tenant_id, campaign_id, platform_group_id, name, bid, status, created_at, updated_at
FROM ads_ad_group WHERE tenant_id = #{tenantId} AND campaign_id = #{campaignId}
ORDER BY name ASC

